import{_ as s}from"./chunks/benchmark.JDxUlm17.js";import{_ as t,o as r,c as n,ag as a}from"./chunks/framework.DqVSm8kp.js";const g=JSON.parse('{"title":"Benchmark","description":"","frontmatter":{},"headers":[],"relativePath":"fr/guide/benchmark.md","filePath":"fr/guide/benchmark.md"}'),o={name:"fr/guide/benchmark.md"};function i(l,e,u,d,c,m){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="benchmark" tabindex="-1">Benchmark <a class="header-anchor" href="#benchmark" aria-label="Permalink to &quot;Benchmark&quot;">​</a></h1><p>La page Benchmark execute des evaluations standardisees sur vos modeles locaux en utilisant de vrais logprobs de tokens, vous fournissant des donnees de performance objectives.</p><p><strong>Element de la barre laterale :</strong> Benchmark <strong>Route :</strong> <code>/benchmark</code></p><p><img src="'+s+'" alt="Interface Benchmark"></p><h2 id="qu-est-ce-que-le-benchmark-chirurgical" tabindex="-1">Qu&#39;est-ce que le Benchmark Chirurgical ? <a class="header-anchor" href="#qu-est-ce-que-le-benchmark-chirurgical" aria-label="Permalink to &quot;Qu&#39;est-ce que le Benchmark Chirurgical ?&quot;">​</a></h2><p>Contrairement aux benchmarks classiques qui verifient simplement si la reponse est correcte, le Benchmark Chirurgical de LLMxRay capture de <strong>vrais logprobs de tokens</strong> via le endpoint compatible OpenAI d&#39;Ollama (<code>/v1/chat/completions</code>). Cela vous donne des donnees de confiance authentiques pour chaque reponse, et pas seulement la precision.</p><h2 id="suites-de-tests-integrees" tabindex="-1">Suites de tests integrees <a class="header-anchor" href="#suites-de-tests-integrees" aria-label="Permalink to &quot;Suites de tests integrees&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Suite</th><th>Questions</th><th>Ce qu&#39;elle evalue</th></tr></thead><tbody><tr><td><strong>ARC</strong></td><td>Raisonnement scientifique</td><td>Questions de sciences niveau college</td></tr><tr><td><strong>GSM8K</strong></td><td>Problemes mathematiques</td><td>Raisonnement arithmetique en plusieurs etapes</td></tr><tr><td><strong>HellaSwag</strong></td><td>Completion de phrases</td><td>Raisonnement de bon sens</td></tr><tr><td><strong>MMLU-Pro</strong></td><td>Multi-disciplines</td><td>Connaissances academiques larges dans differents domaines</td></tr><tr><td><strong>TruthfulQA</strong></td><td>Veracite</td><td>Resistance aux idees recues erronees</td></tr></tbody></table><h2 id="lancer-un-benchmark" tabindex="-1">Lancer un benchmark <a class="header-anchor" href="#lancer-un-benchmark" aria-label="Permalink to &quot;Lancer un benchmark&quot;">​</a></h2><ol><li>Selectionnez un <strong>modele</strong> dans le menu deroulant.</li><li>Choisissez une ou plusieurs <strong>suites de tests</strong>.</li><li>Cliquez sur <strong>Lancer</strong>. Le benchmark diffuse les resultats en temps reel.</li></ol><p>Pendant l&#39;execution, vous pouvez voir :</p><ul><li><strong>Progression en direct</strong> -- Nombre de questions, precision actuelle</li><li><strong>Resultats par question</strong> -- Correct/incorrect, reponse du modele, scores de confiance</li><li><strong>Donnees de latence</strong> -- TTFT et tokens/sec par question</li></ul><h2 id="modeles-de-raisonnement" tabindex="-1">Modeles de raisonnement <a class="header-anchor" href="#modeles-de-raisonnement" aria-label="Permalink to &quot;Modeles de raisonnement&quot;">​</a></h2><p>Pour les modeles de raisonnement comme DeepSeek-R1, le benchmark utilise des <strong>budgets de tokens dynamiques</strong> -- accordant au modele plus de tokens pour ses blocs <code>&lt;think&gt;</code> sans les compter dans la reponse. Cela garantit que les modeles de raisonnement ne sont pas penalises pour avoir montre leur cheminement.</p><h2 id="visualisation-des-resultats" tabindex="-1">Visualisation des resultats <a class="header-anchor" href="#visualisation-des-resultats" aria-label="Permalink to &quot;Visualisation des resultats&quot;">​</a></h2><p>Apres completion, les resultats sont affiches sous forme de :</p><ul><li><strong>Score de precision</strong> -- Pourcentage global de bonnes reponses</li><li><strong>Detail par categorie</strong> -- Precision par domaine au sein de chaque suite</li><li><strong>Graphique radar</strong> -- Comparaison visuelle entre les categories</li><li><strong>Distribution de confiance</strong> -- Histogramme des scores de confiance bases sur les logprobs</li></ul><h2 id="comparer-les-resultats" tabindex="-1">Comparer les resultats <a class="header-anchor" href="#comparer-les-resultats" aria-label="Permalink to &quot;Comparer les resultats&quot;">​</a></h2><p>Lancez la meme suite sur plusieurs modeles pour comparer :</p><ul><li>Quel modele est le plus precis sur quels sujets</li><li>Calibration de la confiance -- une confiance elevee correspond-elle a des reponses correctes ?</li><li>Compromis vitesse vs. precision</li></ul><p>Les resultats sont stockes dans IndexedDB, ce qui vous permet de comparer entre les sessions.</p><h2 id="suites-personnalisees" tabindex="-1">Suites personnalisees <a class="header-anchor" href="#suites-personnalisees" aria-label="Permalink to &quot;Suites personnalisees&quot;">​</a></h2><p>Cliquez sur <strong>Importer</strong> pour charger une suite de benchmark personnalisee. Le format attendu est un fichier JSON contenant :</p><ul><li>Nom et description de la suite</li><li>Tableau de questions, chacune avec : texte de la question, choix de reponses, index de la reponse correcte et categorie optionnelle</li></ul><h2 id="astuces" tabindex="-1">Astuces <a class="header-anchor" href="#astuces" aria-label="Permalink to &quot;Astuces&quot;">​</a></h2><ul><li><strong>Les logprobs necessitent le endpoint <code>/v1</code></strong> -- Cela utilise l&#39;API compatible OpenAI d&#39;Ollama, et non le endpoint natif <code>/api</code>.</li><li><strong>Commencez par des suites plus petites</strong> -- Demarrez avec un sous-ensemble pour estimer la duree d&#39;une execution complete.</li><li><strong>Reprise possible</strong> -- Si un benchmark est interrompu, vous pouvez reprendre la ou il s&#39;est arrete.</li><li><strong>Comparer les quantifications</strong> -- Lancez le meme modele en Q4 et Q8 pour mesurer l&#39;impact sur la precision.</li></ul>',26)])])}const b=t(o,[["render",i]]);export{g as __pageData,b as default};
